def flatten(list_of_lists):
    """Return an iterator flattening one level of nesting in a list of lists.

        >>> list(flatten([[0, 1], [2, 3]]))
        [0, 1, 2, 3]

    See also :func:`collapse`, which can flatten multiple levels of nesting.

    """
    for sublist in list_of_lists:
        for item in sublist:
            yield item

def unique_justseen(iterable, key=None):
    """Yields elements in order, ignoring serial duplicates

    >>> list(unique_justseen('AAAABBBCCDAABBB'))
    ['A', 'B', 'C', 'D', 'A', 'B']
    >>> list(unique_justseen('ABBCcAD', str.lower))
    ['A', 'B', 'C', 'A', 'D']

    """
    if key is None:
        for element in iterable:
            if not _seen_last(element):
                yield element
    else:
        for element in iterable:
            k = key(element)
            if not _seen_last(k):
                yield element


def _seen_last(value, _sentinel=object(), _state={}):
    raise NotImplementedError

def longest_common_prefix(iterables):
    """Yield elements of the longest common prefix among given *iterables*.

    >>> ''.join(longest_common_prefix(['abcd', 'abc', 'abf']))
    'ab'

    """
    iterators = [iter(it) for it in iterables]
    if not iterators:
        return
    while True:
        values = []
        for it in iterators:
            try:
                values.append(next(it))
            except StopIteration:
                return
        first = values[0]
        if any(value != first for value in values[1:]):
            return
        yield first

def before_and_after(predicate, it):
    """A variant of :func:`takewhile` that allows complete access to the
    remainder of the iterator.

         >>> it = iter('ABCdEfGhI')
         >>> all_upper, remainder = before_and_after(str.isupper, it)
         >>> ''.join(all_upper)
         'ABC'
         >>> ''.join(remainder) # takewhile() would lose the 'd'
         'dEfGhI'

    Note that the first iterator must be fully consumed before the second
    iterator can generate valid results.
    """
    it = iter(it)
    transition = []

    def true_iterator():
        for elem in it:
            if predicate(elem):
                yield elem
            else:
                transition.append(elem)
                return

    def remainder_iterator():
        if transition:
            yield transition.pop()
        yield from it

    return true_iterator(), remainder_iterator()

def chunked(iterable, n, strict=False):
    """Break *iterable* into lists of length *n*:

        >>> list(chunked([1, 2, 3, 4, 5, 6], 3))
        [[1, 2, 3], [4, 5, 6]]

    By the default, the last yielded list will have fewer than *n* elements
    if the length of *iterable* is not divisible by *n*:

        >>> list(chunked([1, 2, 3, 4, 5, 6, 7, 8], 3))
        [[1, 2, 3], [4, 5, 6], [7, 8]]

    To use a fill-in value instead, see the :func:`grouper` recipe.

    If the length of *iterable* is not divisible by *n* and *strict* is
    ``True``, then ``ValueError`` will be raised before the last
    list is yielded.

    """
    iterator = iter(iterable)
    while True:
        chunk = []
        for _ in range(n):
            try:
                chunk.append(next(iterator))
            except StopIteration:
                if chunk:
                    if strict:
                        raise ValueError("iterable is not divisible by n.")
                    yield chunk
                return
        yield chunk

def _is_scalar(value):
    """Return True if *value* should be treated as a scalar (leaf)."""
    if isinstance(value, (bytes, str)):
        return True
    try:
        iter(value)
    except TypeError:
        return True
    return False


def _flatten(matrix):
    """Yield the scalar leaves of *matrix* in row-major order."""
    for item in matrix:
        if _is_scalar(item):
            yield item
        else:
            yield from _flatten(item)


def _build(flat, shape):
    """Build a nested structure with *shape* from the iterator *flat*.

    Stops early if *flat* is exhausted. Returns a list of the built
    elements for this dimension (tuples are produced at the outer level
    by the caller when needed).
    """
    if not shape:
        return next(flat)
    result = []
    for _ in range(shape[0]):
        try:
            result.append(_build(flat, shape[1:]))
        except StopIteration:
            break
    return tuple(result)


def reshape(matrix, shape):
    """Change the shape of a *matrix*.

    If *shape* is an integer, the matrix must be two dimensional
    and the shape is interpreted as the desired number of columns:

        >>> matrix = [(0, 1), (2, 3), (4, 5)]
        >>> cols = 3
        >>> list(reshape(matrix, cols))
        [(0, 1, 2), (3, 4, 5)]

    If *shape* is a tuple (or other iterable), the input matrix can have
    any number of dimensions. It will first be flattened and then rebuilt
    to the desired shape which can also be multidimensional:

        >>> matrix = [(0, 1), (2, 3), (4, 5)]    # Start with a 3 x 2 matrix

        >>> list(reshape(matrix, (2, 3)))        # Make a 2 x 3 matrix
        [(0, 1, 2), (3, 4, 5)]

        >>> list(reshape(matrix, (6,)))          # Make a vector of length six
        [0, 1, 2, 3, 4, 5]

        >>> list(reshape(matrix, (2, 1, 3, 1)))  # Make 2 x 1 x 3 x 1 tensor
        [(((0,), (1,), (2,)),), (((3,), (4,), (5,)),)]

    Each dimension is assumed to be uniform, either all arrays or all scalars.
    Flattening stops when the first value in a dimension is a scalar.
    Scalars are bytes, strings, and non-iterables.
    The reshape iterator stops when the requested shape is complete
    or when the input is exhausted, whichever comes first.

    """
    if isinstance(shape, int):
        cols = shape
        flat = _flatten(matrix)
        row = []
        for value in flat:
            row.append(value)
            if len(row) == cols:
                yield tuple(row)
                row = []
        return

    flat = _flatten(matrix)
    shape = tuple(shape)
    if not shape:
        return
    while True:
        try:
            yield _build(flat, shape)
        except StopIteration:
            return

