from collections.abc import Iterable


def _is_scalar(value):
    """Return True if *value* should be treated as a scalar (leaf) value."""
    if isinstance(value, (bytes, str)):
        return True
    return not isinstance(value, Iterable)


def _flatten(matrix):
    """Yield the scalar values of *matrix* in row-major order.

    Flattening stops descending into a dimension once its first
    value is a scalar, so each dimension is assumed to be uniform.
    """
    if _is_scalar(matrix):
        yield matrix
        return
    for item in matrix:
        if _is_scalar(item):
            yield item
        else:
            yield from _flatten(item)


def _build(values, shape):
    """Consume values from the iterator *values* to build *shape*.

    Returns a nested tuple. Stops early if the input is exhausted.
    """
    if not shape:
        return next(values)
    size = shape[0]
    rest = shape[1:]
    result = []
    for _ in range(size):
        if not rest:
            try:
                result.append(next(values))
            except StopIteration:
                break
        else:
            sub = []
            try:
                sub = _build(values, rest)
            except StopIteration:
                break
            result.append(sub)
    return tuple(result)


def reshape(matrix, shape):
    """Change the shape of a *matrix*.

    If *shape* is an integer, the matrix must be two dimensional
    and the shape is interpreted as the desired number of columns:

        >>> matrix = [(0, 1), (2, 3), (4, 5)]
        >>> cols = 3
        >>> list(reshape(matrix, cols))
        [(0, 1, 2), (3, 4, 5)]

    If *shape* is a tuple (or other iterable), the input matrix can have
    any number of dimensions. It will first be flattened and then rebuilt
    to the desired shape which can also be multidimensional:

        >>> matrix = [(0, 1), (2, 3), (4, 5)]    # Start with a 3 x 2 matrix

        >>> list(reshape(matrix, (2, 3)))        # Make a 2 x 3 matrix
        [(0, 1, 2), (3, 4, 5)]

        >>> list(reshape(matrix, (6,)))          # Make a vector of length six
        [0, 1, 2, 3, 4, 5]

        >>> list(reshape(matrix, (2, 1, 3, 1)))  # Make 2 x 1 x 3 x 1 tensor
        [(((0,), (1,), (2,)),), (((3,), (4,), (5,)),)]

    Each dimension is assumed to be uniform, either all arrays or all scalars.
    Flattening stops when the first value in a dimension is a scalar.
    Scalars are bytes, strings, and non-iterables.
    The reshape iterator stops when the requested shape is complete
    or when the input is exhausted, whichever comes first.

    """
    if isinstance(shape, int):
        shape = (shape,)
        # Integer form: rows are yielded, each with `shape` columns.
        values = _flatten(matrix)
        while True:
            row = []
            for _ in range(shape[0]):
                try:
                    row.append(next(values))
                except StopIteration:
                    break
            if not row:
                return
            yield tuple(row)
            if len(row) < shape[0]:
                return
    else:
        shape = tuple(shape)
        values = _flatten(matrix)
        if not shape:
            try:
                yield next(values)
            except StopIteration:
                pass
            return
        # Yield the outermost dimension's items as a sequence of sub-shapes.
        outer, rest = shape[0], shape[1:]
        for _ in range(outer):
            try:
                item = _build(values, rest)
            except StopIteration:
                return
            yield item
